def lookup_many(mapping, keys):
    result = []
    for key in keys:
        if key in mapping:
            result.append((True, mapping[key]))
        else:
            result.append((False, None))
    return result

print(lookup_many({}, ["A"]))
print(lookup_many({"A": 0, "B": None}, ["A", "B", "C", "A"]))
print(lookup_many({"A": 1}, []))

def apply_updates(updates):
    result = {}
    for key, value in updates:
        result[key] = value
    return result

print(apply_updates([]))
print(apply_updates([("A", 0), ("A", 2), ("B", 0)]))
print(apply_updates([("B", None), ("A", 1), ("B", 3)]))
